function shuffle<T>(arr: T[]): T[] {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}

const main = async () => {
    try {
        console.log('Seeding: ЕГЭ Математика Профиль → Unit 9 → Задачи с прикладным содержанием');

        const [unit] = await db.insert(schema.units).values({
            title: '9. Задачи с прикладным содержанием',
            description: 'Физика, экономика и инженерные формулы: подстановка данных и решение уравнений/неравенств',
            courseId: COURSE_ID,
            order: UNIT_ORDER,
            imageSrc: 'LottieUnit9',
        }).returning();
        console.log(`unit: ${unit.id} "${unit.title}"`);

        for (const lessonSeed of lessons) {
            const [lesson] = await db.insert(schema.lessons).values({
                title: lessonSeed.title,
                unitId: unit.id,
                order: lessonSeed.order,
            }).returning();
            console.log(`  lesson: ${lesson.id} "${lesson.title}" (${lessonSeed.challenges.length})`);

            for (let i = 0; i < lessonSeed.challenges.length; i++) {
                const c = lessonSeed.challenges[i];
                const [challenge] = await db.insert(schema.challenges).values({
                    lessonId: lesson.id,
                    type: 'ASSIST',
                    question: c.question,
                    order: i + 1,
                    points: 10,
                    author: AUTHOR,
                    difficulty: '',
                    imageSrc: '',
                }).returning();

                const options = shuffle([
                    { text: c.correct, correct: true },
                    ...c.distractors.map((d) => ({ text: d, correct: false })),
                ]);

                await db.insert(schema.challengeOptions).values(
                    options.map((o) => ({
                        challengeId: challenge.id,
                        text: o.text,
                        correct: o.correct,
                    }))
                );
            }
        }

        console.log('Готово!');
    } catch (error) {
        console.error(error);
        throw new Error('Не получилось заполнить БД');
    } finally {
        await queryClient.end();
    }
};

main();
